"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[5517],{55517:e=>{e.exports=JSON.parse('{"slug":"klyuchevaya-stavka-23-oktyabrya-2026-pauza","locale":"es","title":"25 de 26 economistas esperan que el Banco de Rusia mantenga el 14% el 23 de octubre","description":"Casi todos esperan que el 23 de octubre de 2026 se mantenga el 14%. Por qu\xe9 contin\xfaa la pausa y qu\xe9 significa para dep\xf3sitos y pr\xe9stamos.","blocks":[{"id":"b001","kind":"paragraph","text":"El Banco de Rusia anunciar\xe1 el 23 de octubre de 2026 el tipo oficial y actualizar\xe1 su previsi\xf3n. De 26 economistas consultados, 25 esperan mantener el 14% y uno prev\xe9 el 13,75%. Alexander Vedyakhin, de Sberbank, tambi\xe9n considera m\xe1s probable mantenerlo. Desde el 6 de junio de 2025 baj\xf3 del 21% al 14% en julio de 2026; el 11 de septiembre lleg\xf3 la primera pausa. Algunos economistas creen que durar\xe1 hasta diciembre. La \xfaltima reuni\xf3n de 2026 ser\xe1 el 18 de diciembre."},{"id":"b002","kind":"paragraph","text":"Los precios explican la pausa. Del 1 de enero al 12 de octubre crecieron un 6,1%; Econom\xeda estima una inflaci\xf3n interanual del 7,22%, frente a la previsi\xf3n del 6–7% para 2026. Elvira Nabiullina explic\xf3 el 11 de septiembre que detuvieron los recortes por factores puntuales ajenos a los tipos, como interrupciones productivas y combustible caro. Pero la inflaci\xf3n persistente se estim\xf3 en el 5–6% anualizado, por encima de la meta del 4%."},{"id":"b003","kind":"paragraph","text":"Las expectativas muestran c\xf3mo un salto puede persistir. Un peluquero espera que alquiler y tinte suban un 14% anual y encarece hoy el corte. Su cliente, esperando lo mismo, compra ya un televisor con cr\xe9dito. Los precios suben porque se espera que suban. Son expectativas inflacionarias. En septiembre se esperaba un 14,2% para el a\xf1o siguiente, frente al 13,7% en agosto, casi el doble del 7,22% efectivo."},{"id":"b004","kind":"paragraph","text":"El propio Banco de Rusia a\xf1ade una condici\xf3n: los recortes de 2027 dependen de que disminuya el d\xe9ficit. Si el Estado gasta m\xe1s de lo que recauda, a\xf1ade demanda y acelera los precios."},{"id":"b005","kind":"paragraph","text":"Para quien ahorra, la pausa mantiene la remuneraci\xf3n: el promedio m\xe1ximo de los 10 mayores bancos al cierre de septiembre era del 13,05%. Para quien pide prestado, cr\xe9ditos e hipotecas de mercado siguen caros. Si el 23 de octubre se mantiene el tipo, la pr\xf3xima oportunidad de recorte ser\xe1 el 18 de diciembre."},{"id":"b006","kind":"paragraph","text":"Quien abra ahora un dep\xf3sito anual fija cerca del 13%. Gana si los tipos bajan antes de lo previsto; pierde la oportunidad de m\xe1s intereses si deben subir. Esperar cr\xe9dito barato cuesta al menos 2 meses, durante los que los precios seguir\xe1n creciendo. La previsi\xf3n del 23 de octubre mostrar\xe1 cu\xe1nto tiempo se plantea mantener el tipo."},{"id":"b007","kind":"heading","text":"\xbfQu\xe9 decisi\xf3n se espera el 23 de octubre de 2026?"},{"id":"b008","kind":"paragraph","text":"Casi todos esperan mantener el 14%: de 26 economistas, 25 eligen esa opci\xf3n y uno prev\xe9 el 13,75%. Sberbank tambi\xe9n considera m\xe1s probable la continuidad."},{"id":"b009","kind":"heading","text":"\xbfPor qu\xe9 no baja el Banco de Rusia los tipos?"},{"id":"b010","kind":"paragraph","text":"Los precios llevan un 6,1% desde enero, cerca del techo previsto del 6–7%. Parte del salto es puntual, por combustible e interrupciones, pero la poblaci\xf3n espera un 14,2% para el pr\xf3ximo a\xf1o. El regulador teme que el repunte se vuelva persistente."},{"id":"b011","kind":"heading","text":"\xbfQu\xe9 implica la pausa para dep\xf3sitos e hipotecas?"},{"id":"b012","kind":"paragraph","text":"Con el 14%, los dep\xf3sitos siguen rentables: el promedio m\xe1ximo de los grandes bancos al cierre de septiembre era del 13,05%. Los cr\xe9ditos e hipotecas de mercado siguen caros. Despu\xe9s del 23 de octubre, la pr\xf3xima decisi\xf3n llegar\xe1 el 18 de diciembre."}],"sources":[{"label":"Consenso de Vedomosti: casi unanimidad sobre una pausa de tipos","url":"https://www.vedomosti.ru/economics/articles/2026/10/16/1237503-konsensus-prognoz-vedomostei"},{"label":"Sberbank espera mantener el tipo oficial","url":"https://www.kommersant.ru/doc/9026103"},{"label":"Sber prev\xe9 mantener el tipo en octubre","url":"https://www.interfax.ru/business/1122297"},{"label":"Expectativas de inflaci\xf3n y confianza del consumidor de septiembre de 2026","url":"https://www.cbr.ru/analytics/dkp/inflationary_expectations/Infl_exp_26-09/"},{"label":"La inflaci\xf3n rusa del 6 al 12 de octubre es del 0,11%","url":"https://www.interfax.ru/business/1122459"},{"label":"Calendario del Banco de Rusia para los tipos de 2026","url":"https://finance.mail.ru/article/bank-rossii-opublikoval-grafik-zasedaniy-po-klyuchevoy-stavke-na-2026-god-68067122/"},{"label":"El promedio m\xe1ximo de diez bancos sube al 13,05%","url":"https://ria.ru/20261001/bank-2121443529.html"},{"label":"El Banco de Rusia baja el tipo al 20% anual","url":"https://finance.mail.ru/article/bank-rossii-snizil-klyuchevuyu-stavku-do-20-godovyh-66466367/"},{"label":"El Banco de Rusia eleva su previsi\xf3n de inflaci\xf3n para 2026","url":"https://www.kommersant.ru/doc/8843971"}],"sourceBodySha256":"fe62eaf826a4de568479af2c8bab712a15f8ab8a8d9f9a89aca0a2ed2e59bfc4"}')}}]);